import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import RideCard from '../components/RideCard';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import { toast } from 'react-toastify';
import { FaToggleOn, FaToggleOff } from 'react-icons/fa';

const CaptainDashboard = () => {
  const { isAuthenticated, captain } = useSelector((state) => state.auth);
  const navigate = useNavigate();

  const [isOnline, setIsOnline] = useState(false);
  const [stats, setStats] = useState({});
  const [earnings, setEarnings] = useState({});
  const [activeRide, setActiveRide] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login');
      return;
    }

    fetchDashboardData();
  }, [isAuthenticated, navigate]);

  const fetchDashboardData = async () => {
    try {
      const statsRes = await api.get('/captains/ride-stats');
      const earningsRes = await api.get('/captains/earnings');

      setStats(statsRes.data.stats || {});
      setEarnings(earningsRes.data.earnings || {});
      setIsOnline(captain?.isOnline || false);
    } catch (error) {
      toast.error('Failed to load dashboard');
    } finally {
      setLoading(false);
    }
  };

  const toggleOnlineStatus = async () => {
    try {
      await api.post('/captains/toggle-online-status', {
        isOnline: !isOnline,
      });
      setIsOnline(!isOnline);
      toast.success(`You are now ${!isOnline ? 'online' : 'offline'}`);
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex flex-col">
        <Header />
        <div className="flex-1 flex items-center justify-center">
          <p>Loading...</p>
        </div>
        <Footer />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />

      <main className="flex-1 p-4 sm:p-6 lg:p-8">
        <div className="max-w-7xl mx-auto">
          {/* Welcome Section */}
          <div className="bg-gradient-to-r from-green-600 to-green-800 text-white rounded-lg p-6 mb-8">
            <div className="flex justify-between items-center">
              <div>
                <h1 className="text-3xl font-bold mb-2">Welcome, {captain?.fullName}!</h1>
                <p className="text-green-100">Ready to earn more?</p>
              </div>
              <button
                onClick={toggleOnlineStatus}
                className={`px-6 py-3 rounded-lg font-bold flex items-center gap-2 ${
                  isOnline
                    ? 'bg-green-700 hover:bg-green-800'
                    : 'bg-red-600 hover:bg-red-700'
                } transition`}
              >
                {isOnline ? (
                  <>
                    <FaToggleOn /> Go Offline
                  </>
                ) : (
                  <>
                    <FaToggleOff /> Go Online
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Stats Section */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
            {[
              { label: 'Today Earnings', value: `₹${earnings.periodEarnings || 0}`, icon: '💰' },
              { label: 'Total Earnings', value: `₹${earnings.totalEarnings || 0}`, icon: '🏆' },
              { label: 'Completed Rides', value: stats.completedRides || 0, icon: '✅' },
              { label: 'Rating', value: `${stats.averageRating || 0}/5`, icon: '⭐' },
            ].map((stat, index) => (
              <div key={index} className="bg-white rounded-lg p-4 shadow-md">
                <p className="text-3xl mb-2">{stat.icon}</p>
                <p className="text-gray-600 text-sm">{stat.label}</p>
                <p className="text-2xl font-bold text-gray-800">{stat.value}</p>
              </div>
            ))}
          </div>

          {/* Action Buttons */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-8">
            <button
              onClick={() => navigate('/captain-rides')}
              className="bg-blue-600 text-white py-3 rounded-lg hover:bg-blue-700 font-bold transition"
            >
              View Available Rides
            </button>
            <button
              onClick={() => navigate('/captain-profile')}
              className="bg-purple-600 text-white py-3 rounded-lg hover:bg-purple-700 font-bold transition"
            >
              My Profile
            </button>
          </div>

          {/* Active Ride Display */}
          {activeRide && (
            <div className="bg-white rounded-lg shadow-md p-6 mb-8">
              <h2 className="text-2xl font-bold mb-4">Current Ride</h2>
              <RideCard ride={activeRide} />
            </div>
          )}
        </div>
      </main>

      <Footer />
    </div>
  );
};

export default CaptainDashboard;
